package com.mhtextractor.uiport;

import java.util.List;
import java.util.Map;
import java.util.Objects;

/**
 * 端口事件（sealed）：工作区结构变更 / 运行状态 / 提醒。
 *
 * <p>文案一律「键 + 具名参数」（方案 §14 决策 13），渲染属前端；本包不得依赖任何国际化工具类。</p>
 */
public sealed interface PortEvent {

    /**
     * 参数状态变更类别（B4）：后端参数命令完成「写入 + 撤销压栈 + 磁盘缓存失效（规则 a）」后
     * 按此类别发布 {@link ParamStateChanged}；前端据此决定列表刷新与参数色刷新的粒度。
     */
    enum ParamChangeKind {
        /** 全局已确认参数写入（{@code applyConfirmedParams} 语义）：全部条目受影响 */
        SET_GLOBAL,
        /** 组参数写入（{@code applyGroupParams} 语义）：该组未移除成员受影响 */
        SET_GROUP,
        /** 条目级参数写入（{@code applyItemParams} 语义）：该条目受影响 */
        SET_ITEM,
        /** 目标生效参数应用到全局（{@code applyGlobalParamsTo} 语义）：全部条目受影响 */
        APPLY_GLOBAL,
        /** 清除参数（{@code clearParamsForTargets} 语义，单条撤销）：被清除目标及组内成员受影响 */
        CLEAR
    }

    /**
     * 参数状态变更（B4）：后端已完成参数写入、撤销压栈与磁盘缓存失效；
     * 前端按 {@link #kind()} 执行对应的列表刷新与参数色刷新链（事件在命令线程同步送达）。
     *
     * @param kind          变更类别
     * @param imageMode     本次变更作用的模式（true = 图片，false = 文本）
     * @param affectedPaths 受影响条目路径（SET_GLOBAL / APPLY_GLOBAL = 全部条目含已移除；
     *                      其余 = 实际受影响条目；不可变副本）
     */
    record ParamStateChanged(ParamChangeKind kind, boolean imageMode, List<String> affectedPaths)
            implements PortEvent {
        public ParamStateChanged {
            Objects.requireNonNull(kind, "kind");
            affectedPaths = List.copyOf(Objects.requireNonNull(affectedPaths, "affectedPaths"));
        }
    }

    /** 取消或全量预解析推进代际；接收方应丢弃旧代际的排队回调。 */
    record WorkspaceActivityChanged(long generation) implements PortEvent {}

    record PreparseProgress(long generation, int done, int total) implements PortEvent {}

    // ---- B5-1：导入编排事件 ----

    /**
     * 导入在途状态变更（B5-1）：{@code importPaths} 建会话后置 true（前端置位「导入中」并禁用开始提取）；
     * 收尾唯一恢复点置 false。generation = 导入会话代际（每次 {@code importPaths} 自增）。
     */
    record ImportStateChanged(long generation, boolean importing) implements PortEvent {}

    /**
     * 一轮导入落地（B5-1）：后端已完成本轮全部模型命令（建组/平铺/追加）与撤销压栈
     * （<b>每轮恰好一条</b>，BC-5），前端据此执行列表全量刷新（每轮一次，RISK-8）、
     * 新建组的名字刷新挂接（F8/RISK-11）与「首轮列表由空转非空」的首行选中。
     *
     * @param generation       导入会话代际
     * @param plan             本轮计划（端口视图模型；含配额/剩余标志）
     * @param newFiles         本轮实际落地的新条目数（已去重；跳过的批次不计）
     * @param newGroups        本轮自动新建的组数
     * @param madeListNonEmpty 本轮首个非跳过批次应用前列表为空（导入首轮选中首行的判定）
     * @param createdGroups    本轮新建的组（模型对象，按落地顺序；前端挂接名字刷新监听）
     */
    record ImportRound(long generation, ImportPlanVm plan, int newFiles, int newGroups,
                       boolean madeListNonEmpty,
                       List<com.mhtextractor.model.GroupItem<com.mhtextractor.model.PreviewItem>> createdGroups)
            implements PortEvent {
        public ImportRound {
            createdGroups = List.copyOf(Objects.requireNonNull(createdGroups, "createdGroups"));
        }
    }

    /**
     * 导入收尾（B5-1）：载荷 = 本次导入全量累计条目的绝对路径（RISK-7：导入期间抑制、
     * 收尾跑一次，避免 O(n²)）。前端判「非空 + 当前模式参数已确认」后调
     * {@code commands().startPreparseFor(paths)} —— 与迁移前 {@code hasConfirmedParams} 门同语义。
     */
    record ImportFinished(long generation, List<String> accumulatedPaths) implements PortEvent {
        public ImportFinished {
            accumulatedPaths = List.copyOf(Objects.requireNonNull(accumulatedPaths, "accumulatedPaths"));
        }
    }

    record PreparseStarted(long generation) implements PortEvent {}

    /** 每完成一个条目交付一次，包括解析失败；不是整批结束通知。 */
    record PreparseFinished(long generation, PreparseResult result) implements PortEvent {}

    /** generation 是独立的预览请求代际；旧任务不得终结新任务的在途状态。 */
    record PreviewLoadStateChanged(long generation, String path, boolean active) implements PortEvent {}

    record PreviewConfirmationRequired(String path, String name, long sizeMiB) implements PortEvent {}

    record PreviewLoadFailed(long generation, String path, boolean fileInfo, String detail) implements PortEvent {}

    record PreviewThumbnail(long generation, String path, int index,
                            com.mhtextractor.model.ThumbnailData thumbnail) implements PortEvent {}

    /** Terminal/repaint signal, also emitted on cancellation or stale completion.
     * A null thumbnail cache means return to the lazy prompt, never reenter loading. */
    record PreviewLoaded(long generation, String path) implements PortEvent {}

    record PreviewRegionConfirmationRequired(long generation, String path) implements PortEvent {}

    record PreviewNotice(long generation, String path, String key) implements PortEvent {}

    // ---- B6：提取任务通道（矩阵处置项 1）----

    /**
     * 提取任务通道事件族（B6）：任务代际 / 终态恰好一次 / 取消竞态 / 结果通道的端口契约 ——
     * {@link ExtractionProgress} / {@link ExtractionTerminal} / {@link ExtractionResult}
     * 都携带递增的 run 代际；旧任务迟到的投递由后端代际守卫拦下（不得污染新任务）。
     */
    non-sealed interface ExtractionChannelEvent extends PortEvent {
    }

    /**
     * 跨单元总进度（0.0~1.0，只增不减；后端 worker 的进度回调经派发器投递）。
     *
     * @param generation run 代际
     * @param overall    总进度
     */
    record ExtractionProgress(long generation, double overall) implements ExtractionChannelEvent {
    }

    /**
     * 提取终态（B6）：<b>恰好一次</b> —— 成功 / 失败在 worker 收尾后交付；取消在
     * {@code cancelExtraction()} 的<b>取消请求时刻</b>交付（取消请求 ≠ worker 已退出）。
     * 前端据此复位停止/开始按钮并渲染结果。
     *
     * @param generation          run 代际
     * @param end                 终态类别
     * @param stats               统计快照（仅 {@link ExtractionEnd#SUCCEEDED} 非 null；
     *                             取消路径的 partial 经 {@link ExtractionResult} 单独交付）
     * @param sessionOutputFolder 本次会话输出目录（成功路径"完成后打开输出目录"用）
     */
    record ExtractionTerminal(long generation, ExtractionEnd end,
                              com.mhtextractor.model.ExtractionStats stats,
                              String sessionOutputFolder) implements ExtractionChannelEvent {
    }

    /**
     * 取消路径的 partial 回写（B6）：worker 完成处理（取消请求之后）恰好投递一次，
     * 载荷 = worker 返回的统计；成功路径统计随 {@link ExtractionTerminal} 走，不重复投递。
     *
     * @param generation run 代际
     * @param stats      已处理单元的 partial 统计
     * @param sessionOutputFolder 本 run 请求冻结的会话输出目录
     */
    record ExtractionResult(long generation,
                            com.mhtextractor.model.ExtractionStats stats,
                            String sessionOutputFolder) implements ExtractionChannelEvent {
        public ExtractionResult(long generation, com.mhtextractor.model.ExtractionStats stats) {
            this(generation, stats, null);
        }
    }

    /** 提取终态类别（B6）：成功 / 失败 / 取消，每任务恰好交付其一。 */
    enum ExtractionEnd {
        /** worker 正常收尾（统计随终态事件交付） */
        SUCCEEDED,
        /** worker 异常收尾（无统计；后端已打 {@code log.maincontroller.37}，前端渲染错误卡片） */
        FAILED,
        /** 取消请求时刻交付（无统计；partial 经 {@link ExtractionResult} 在 worker 收尾后投递） */
        CANCELLED
    }

    /**
     * 工作区结构化变更（数据序 / 分组 / 勾选 / 参数 / 撤销等）。
     *
     * @param kind 变更类别（类别枚举留后续批次定稿；前端据此决定刷新粒度）
     */
    record WorkspaceChanged(String kind) implements PortEvent {
        public WorkspaceChanged {
            Objects.requireNonNull(kind, "kind");
        }
    }

    /**
     * 提取在途状态变更。
     *
     * @param running 提取是否在途
     * @param generation run 代际；false 不表示 worker 已退出
     */
    record RunningChanged(boolean running, long generation) implements PortEvent {
        public RunningChanged(boolean running) { this(running, 0); }
    }

    /**
     * 提醒（前端按 {@link NoticeLevel} 选择呈现形式：错误居中必点 / 警告·信息右上 toast）。
     *
     * @param key         文案键
     * @param namedParams 具名参数（防御性不可变拷贝）
     * @param level       级别
     */
    record Notice(String key, Map<String, String> namedParams, NoticeLevel level) implements PortEvent {
        public Notice {
            Objects.requireNonNull(key, "key");
            namedParams = Map.copyOf(Objects.requireNonNull(namedParams, "namedParams"));
            Objects.requireNonNull(level, "level");
        }
    }
}
package com.mhtextractor.uiport;

/**
 * 确认往返（最小切片接缝）。
 *
 * <p><b>方案 §14 决策 11</b>：卡片被断开/顶替 = 按「取消」交付；超时按请求内 {@code timeoutMs} 兜底；
 * 前端渲染卡片，答案经 {@link ConfirmToken} 回传，恰好交付一次
 * （{@code answer} / {@code cancel} / 超时兜底三选一）。</p>
 */
public interface Confirmer {

    /**
     * 发起一次确认往返。
     *
     * @param request 确认请求（文案 = 键 + 具名参数，决策 13）
     * @return 答案通道；后端保证恰好交付一次
     */
    ConfirmToken confirm(ConfirmRequest request);
}
package com.mhtextractor.uiport;

import java.util.function.Consumer;

/**
 * 工作区变更事件流（最小切片）。
 *
 * <p>事件种类见 {@link PortEvent}：结构化变更（{@link PortEvent.WorkspaceChanged}）、
 * 运行状态（{@link PortEvent.RunningChanged}）、提醒（{@link PortEvent.Notice}）。</p>
 */
public interface PortEvents {

    /**
     * 订阅事件；返回句柄 {@code close()} 即退订。
     *
     * @param listener 同步回调（后端保证按序送达）
     * @return 退订句柄（{@link AutoCloseable#close()}）
     */
    AutoCloseable subscribe(Consumer<PortEvent> listener);
}

package com.mhtextractor.app;

import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.databind.DeserializationFeature;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ObjectNode;
import com.mhtextractor.backend.BackendIdentity;
import com.mhtextractor.backend.BackendLauncher;
import com.mhtextractor.uiport.ConfirmRequest;

import java.io.IOException;
import java.time.Duration;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.ArrayList;
import java.util.Map;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.function.Consumer;

/** Owns the companion process and its pipes; view callbacks never perform IO or wait for a worker. */
public final class BackendSession implements AutoCloseable {
    public enum State { CONNECTING, CONNECTED, CONFIRMING, UNAVAILABLE, DISCONNECTED, CLOSED }
    public enum End { ANSWERED, REPLACED, TIMEOUT, ACTIVITY_FINISHED, DISCONNECTED }
    public record Status(State state, String detail) { }
    public interface View {
        void statusChanged(Status status);
        void confirmationRequested(String id, ConfirmRequest request, Consumer<String> answer);
        void confirmationFinished(String id, End reason);
        default void confirmationAnswerReceived(String id, boolean accepted) { }
    }

    private final ObjectMapper json = new ObjectMapper().enable(DeserializationFeature.FAIL_ON_TRAILING_TOKENS)
            .enable(JsonParser.Feature.STRICT_DUPLICATE_DETECTION);
    private final Consumer<Runnable> dispatch;
    private final View view;
    private final ScheduledExecutorService writes = Executors.newSingleThreadScheduledExecutor(
            Thread.ofPlatform().name("backend-session-write").daemon(true).factory());
    private final Map<String, CompletableFuture<JsonNode>> requests = new LinkedHashMap<>();
    private BackendLauncher.Connection connection;
    private Pending pending;
    private boolean started;
    private boolean closed;
    private long sequence;

    public BackendSession(Consumer<Runnable> dispatch, View view) {
        this.dispatch = java.util.Objects.requireNonNull(dispatch);
        this.view = java.util.Objects.requireNonNull(view);
    }

    public void start(String locale) {
        start(() -> BackendExecutable.command(locale), Duration.ofSeconds(10));
    }

    @FunctionalInterface public interface Command { ProcessBuilder create() throws IOException; }

    /** Also supports JVM --serve hosts; identity always comes from this client's filtered build resource. */
    public synchronized void start(Command command, Duration timeout) {
        if (started || closed) throw new IllegalStateException("Backend session can only start once");
        started = true;
        status(State.CONNECTING, "");
        Thread.ofPlatform().name("backend-session-read").daemon(true).start(() -> read(command, timeout));
    }

    private void read(Command command, Duration timeout) {
        BackendLauncher.Connection launched = null;
        boolean welcomed = false;
        try {
            launched = BackendLauncher.launch(command.create(), BackendIdentity.current(), timeout);
            List<String> required = List.of("workspace", "setChecked", "workspacePage", "bulkFiles", "confirmationRoundTrip");
            if (!launched.confirmationRoundTrip() || !launched.capabilities().containsAll(required)) {
                throw new IOException("Backend welcome lacks required capabilities: " + required
                        + "; declared " + launched.capabilities() + ", confirmationRoundTrip=" + launched.confirmationRoundTrip());
            }
            synchronized (this) {
                if (closed) return;
                connection = launched;
                welcomed = true;
                status(State.CONNECTED, launched.identity().version() + " / " + launched.identity().buildId());
            }
            String line;
            while ((line = launched.output().readLine()) != null) receive(json.readTree(line));
            throw new IOException("Backend exited or disconnected (stdout EOF)");
        } catch (Exception error) {
            synchronized (this) {
                if (!closed) {
                    closed = true;
                    finishPending(End.DISCONNECTED);
                    failRequests(error);
                    status(welcomed ? State.DISCONNECTED : State.UNAVAILABLE, error.getMessage());
                }
            }
        } finally {
            // Closing pipes / waiting for process exit is confined to this daemon, never the view thread.
            if (launched != null) {
                try { launched.close(); } catch (IOException ignored) { }
            }
            writes.shutdownNow();
        }
    }

    private synchronized void receive(JsonNode frame) throws IOException {
        if (closed) return;
        if (frame == null || !frame.isObject() || !frame.path("v").isIntegralNumber()
                || frame.path("v").intValue() != 1) throw new IOException("Malformed backend IPC frame");
        String type = frame.path("type").asText();
        if (type.equals("response") || type.equals("error")) {
            CompletableFuture<JsonNode> result = requests.remove(frame.path("id").asText());
            if (result != null) {
                if (type.equals("error")) result.completeExceptionally(new IOException(frame.path("error").toString()));
                else result.complete(frame.path("result"));
            }
            return;
        }
        if (!type.equals("event")) throw new IOException("Unknown backend frame type: " + type);
        String event = frame.path("event").asText();
        JsonNode data = frame.path("data");
        if (event.equals("confirmationRequested")) {
            ConfirmRequest request = confirmation(data);
            if (pending != null) answer(pending.id, null, End.REPLACED);
            Pending next = new Pending(data.path("confirmationId").textValue());
            pending = next;
            status(State.CONFIRMING, next.id);
            dispatch.accept(() -> view.confirmationRequested(next.id, request,
                    action -> answer(next.id, action, End.ANSWERED)));
            // The server's deadline starts before receipt. Give its expiry event a short delivery margin.
            next.timer = writes.schedule(() -> answer(next.id, null, End.TIMEOUT),
                    Math.min(request.timeoutMs(), 30_000) + 250, TimeUnit.MILLISECONDS);
        } else if (event.equals("confirmationExpired")) {
            if (pending != null && pending.id.equals(data.path("confirmationId").asText())) {
                finishPending(End.TIMEOUT);
                status(State.CONNECTED, "");
            }
        } else if (event.equals("extractionTerminal") || event.equals("importFinished")) {
            if (pending != null) {
                finishPending(End.ACTIVITY_FINISHED);
                status(State.CONNECTED, "");
            }
        }
    }

    private ConfirmRequest confirmation(JsonNode data) throws IOException {
        if (!data.path("confirmationId").isTextual() || data.path("confirmationId").asText().isBlank()
                || !data.path("key").isTextual() || data.path("key").asText().isBlank()
                || !data.path("namedParams").isObject() || !data.path("actionKeys").isArray()
                || !data.has("defaultAction") || !data.path("defaultAction").isNull()
                || !data.path("timeoutMs").isIntegralNumber() || !data.path("timeoutMs").canConvertToLong()
                || data.path("timeoutMs").longValue() <= 0) throw new IOException("Malformed backend confirmation");
        Map<String, String> params = new LinkedHashMap<>();
        var fields = data.path("namedParams").fields();
        while (fields.hasNext()) {
            var field = fields.next();
            if (!field.getValue().isTextual()) throw new IOException("Confirmation parameters must be strings");
            params.put(field.getKey(), field.getValue().textValue());
        }
        List<String> actions = new ArrayList<>();
        for (JsonNode action : data.path("actionKeys")) {
            if (!action.isTextual() || action.asText().isBlank()) throw new IOException("Invalid confirmation action");
            actions.add(action.textValue());
        }
        return new ConfirmRequest(data.path("key").textValue(), params, actions, data.path("timeoutMs").longValue());
    }

    private synchronized void answer(String id, String action, End reason) {
        if (closed || pending == null || !pending.id.equals(id)) return;
        finishPending(reason);
        status(State.CONNECTED, "");
        ObjectNode params = json.createObjectNode().put("confirmationId", id);
        if (action == null) params.putNull("actionKey"); else params.put("actionKey", action);
        request("confirmAnswer", params).whenComplete((result, error) -> {
            if (error == null) {
                boolean accepted = result.path("accepted").asBoolean();
                dispatch.accept(() -> view.confirmationAnswerReceived(id, accepted));
                if (!accepted && reason == End.ANSWERED) dispatch.accept(() -> view.confirmationFinished(id, End.TIMEOUT));
            }
        });
    }

    /** Explicit IPC commands for companion clients; existing GUI business commands retain their in-process port. */
    public synchronized CompletableFuture<JsonNode> request(String method, JsonNode params) {
        var result = new CompletableFuture<JsonNode>();
        if (closed || connection == null) {
            result.completeExceptionally(new IOException("Backend is not connected"));
            return result;
        }
        String id = "gui-" + ++sequence;
        requests.put(id, result);
        ObjectNode frame = json.createObjectNode().put("v", 1).put("type", "request").put("id", id).put("method", method);
        frame.set("params", params.deepCopy());
        writes.execute(() -> {
            try {
                connection.input().write(json.writeValueAsString(frame));
                connection.input().write('\n');
                connection.input().flush();
            } catch (IOException error) {
                closeWithError(error);
            }
        });
        return result;
    }

    private void closeWithError(IOException error) {
        synchronized (this) {
            if (closed) return;
            closed = true;
            finishPending(End.DISCONNECTED);
            failRequests(error);
            status(State.DISCONNECTED, error.getMessage());
        }
        stopProcess();
    }

    private void finishPending(End reason) {
        if (pending == null) return;
        Pending old = pending;
        pending = null;
        if (old.timer != null) old.timer.cancel(false);
        dispatch.accept(() -> view.confirmationFinished(old.id, reason));
    }

    private void status(State state, String detail) {
        dispatch.accept(() -> view.statusChanged(new Status(state, detail == null ? "" : detail)));
    }

    private void failRequests(Exception error) {
        requests.values().forEach(future -> future.completeExceptionally(error));
        requests.clear();
    }

    @Override public void close() {
        synchronized (this) {
            if (closed) return;
            closed = true;
            finishPending(End.DISCONNECTED);
            failRequests(new IOException("Backend session closed"));
            status(State.CLOSED, "");
        }
        stopProcess();
    }

    private void stopProcess() {
        Thread.ofPlatform().name("backend-session-stop").daemon(true).start(() -> {
            BackendLauncher.Connection current;
            synchronized (this) { current = connection; }
            if (current != null) {
                try { current.close(); } catch (IOException ignored) { }
            }
        });
    }

    private static final class Pending {
        final String id;
        ScheduledFuture<?> timer;
        Pending(String id) { this.id = id; }
    }
}

