/** Explicit v1 projection shared by legacy, paged and event snapshots. */
final class IpcWorkspaceCodec {
    private final ObjectMapper json;
    private final IpcFiles files;

    IpcWorkspaceCodec(ObjectMapper json, IpcFiles files) { this.json = json; this.files = files; }

    ObjectNode item(ItemVm vm) {
        var result = json.createObjectNode().put("id", vm.id()).put("name", vm.name())
                .put("checked", vm.checked()).put("removed", vm.removed())
                .put("unitIndex", vm.unitIndex()).put("update", vm.update().name());
        result.put("sourceFolder", vm.sourceFolder());
        return result;
    }

    ObjectNode workspace(WorkspaceVm vm, long revision) throws IOException {
        var result = json.createObjectNode();
        var groups = result.putArray("groups");
        for (var group : vm.groups()) groups.add(group(group));
        var items = result.putArray("topLevelItems");
        vm.topLevelItems().forEach(i -> items.add(item(i)));
        var order = json.createArrayNode();
        for (TargetId target : vm.topLevelOrder()) order.addObject().put("path", target.path()).put("groupNo", target.groupNo());
        result.set("topLevelOrder", file(order));
        return result.put("canUndo", vm.canUndo()).put("undoDepth", vm.undoDepth())
                .put("selection", vm.selection().name()).put("revision", revision);
    }

    ObjectNode group(com.mhtextractor.uiport.GroupVm vm) {
        var entry = json.createObjectNode().put("no", vm.no()).put("name", vm.name())
                .put("expanded", vm.expanded()).put("defaultNamed", vm.defaultNamed());
        var members = entry.putArray("members");
        vm.members().forEach(m -> members.add(item(m)));
        var folders = entry.putArray("sourceFolders");
        vm.sourceFolders().forEach(folders::add);
        return entry;
    }

    /** Import events also need a full projection in native, where record reflection is unavailable. */
    ObjectNode plan(ImportPlanVm vm) {
        var result = json.createObjectNode().put("ignoredNonMht", vm.ignoredNonMht()).put("hiddenDirs", vm.hiddenDirs())
                .put("emptyDirs", vm.emptyDirs()).put("unreadable", vm.unreadable()).put("depthLimited", vm.depthLimited())
                .put("quotaHit", vm.quotaHit()).put("hasMore", vm.hasMore());
        var batches = result.putArray("batches");
        for (var batch : vm.batches()) {
            var value = batches.addObject().put("dirPath", batch.dirPath()).put("folderName", batch.folderName())
                    .put("grouped", batch.grouped());
            var paths = value.putArray("filePaths");
            batch.filePaths().forEach(paths::add);
        }
        return result;
    }

    ObjectNode file(com.fasterxml.jackson.databind.JsonNode content) throws IOException {
        return files.write(".json", json.writeValueAsBytes(content), "application/json");
    }
}

    IpcServer(IpcSession session) throws IOException {
        this.port = session.port;
        this.session = session;
        this.identity = BackendIdentity.current();
        files = session.files();
        codec = new IpcWorkspaceCodec(json, files);
    }

    void run(InputStream input, OutputStream output) throws IOException {
        welcomed = false;
        // Output is borrowed; the reader closes input on termination. Never swallow transport IO errors.
        IpcOutput writer = new IpcOutput(output);
        boolean outputFailed = false;
        ObjectNode ready = frame("event").put("event", "ready");
        ArrayNode methods = ready.putObject("data").putArray("methods").add("workspace").add("setChecked");
        ready.withObject("data").put("sessionId", sessionId).put("revision", revision);
        if (session != null) {
            IpcSession.METHODS.forEach(methods::add);
            session.silentChanges(() -> revision++);
            session.events(event -> {
                try { emit(writer, event); }
                catch (IOException e) { throw new UncheckedIOException(e); }
            });
        }
        methods.add("hello");
        if (session != null) IpcSession.STRUCTURE_METHODS.forEach(methods::add);
        if (session != null) IpcSession.ACTIVITY_METHODS.forEach(methods::add);
        if (session != null) IpcSession.PARAM_METHODS.forEach(methods::add);
        if (session != null) IpcSession.EXTRACTION_METHODS.forEach(methods::add);
        AutoCloseable subscription = session == null ? port.events().subscribe(event -> {
            if (event instanceof com.mhtextractor.uiport.PortEvent.WorkspaceChanged changed) {
                var frame = frame("event").put("event", "workspaceChanged");
                frame.putObject("data").put("kind", changed.kind());
                try { emit(writer, frame); } catch (IOException e) { throw new UncheckedIOException(e); }
            }
        }) : () -> { };
        disconnected = false;
        deferred.clear();
        try (var incoming = new IpcInput(input)) {
            write(writer, ready); // The first write is covered by the same failure cleanup as all later frames.
            if (session != null) session.inputPump(() -> pump(incoming, writer));
            while (!disconnected) {
                writer.check();
                if (session != null) session.drainCallbacks();
                String line;
                if (!deferred.isEmpty() && (session == null || !session.busy())) line = deferred.removeFirst();
                else {
                    var received = session == null ? incoming.take() : incoming.poll(25);
                    if (received == null) continue;
                    if (received.line() == null) {
                        endInput(received);
                        break;
                    }
                    line = received.line();
                }
                if (session != null && session.busy() && !priority(line)) {
                    defer(line, writer);
                } else write(writer, dispatch(line));
            }
        } catch (UncheckedIOException e) {
            outputFailed = true;
            throw e.getCause();
        } catch (IOException e) {
            outputFailed = true;
            throw e;
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            throw new IOException("IPC host interrupted", e);
        } finally {
            try {
                try { subscription.close(); } catch (Exception e) { throw new IOException(e); }
                if (session != null) {
                    if (outputFailed) session.events(event -> { });
                    session.inputPump(() -> { });
                    try { session.shutdownWorkers(); }
                    finally {
                        session.events(event -> { });
                        session.silentChanges(() -> { });
                    }
                }
                else files.close();
            } finally { writer.close(); }
        }
    }

    private void emit(IpcOutput writer, ObjectNode event) throws IOException {
        var data = (ObjectNode) event.get("data");
        data.put("revision", ++revision);
        if (event.path("event").asText().equals("workspaceChanged")) {
            data.set("snapshot", codec.file(snapshot()));
        }
        write(writer, event);
    }

    private ObjectNode snapshot() throws IOException {
        if (currentSnapshot == null || snapshotRevision != revision) {
            currentSnapshot = codec.workspace(port.queries().workspace(), revision);
            snapshotRevision = revision;
        }
        return currentSnapshot;
    }

    private void endInput(IpcInput.Received received) throws IOException {
